import 'dart:async';
import 'dart:typed_data';
import 'package:flutter/material.dart';
import 'package:record/record.dart';
import 'package:web_socket_channel/io.dart';
import 'package:web_socket_channel/web_socket_channel.dart';

void main() {
  runApp(const PttApp());
  }

  class PttApp extends StatelessWidget {
    const PttApp({super.key});

      @override
        Widget build(BuildContext context) {
            return MaterialApp(
                  title: 'PTT Application',
                        debugShowCheckedModeBanner: false,
                              theme: ThemeData.dark(),
                                    home: const PttHomeScreen(),
                                        );
                                          }
                                          }

                                          enum AppStatus { disconnected, connected, talking, receiving }

                                          class PttHomeScreen extends StatefulWidget {
                                            const PttHomeScreen({super.key});

                                              @override
                                                State<PttHomeScreen> createState() => _PttHomeScreenState();
                                                }

                                                class _PttHomeScreenState extends State<PttHomeScreen> {
                                                  final TextEditingController _ipController = TextEditingController();
                                                    final AudioRecorder _audioRecorder = AudioRecorder();

                                                      AppStatus _status = AppStatus.disconnected;
                                                        String _serverIp = "";
                                                          final int _maxDuration = 10;
                                                            Timer? _talkTimer;
                                                              int _currentTalkTime = 0;
                                                                bool _isLoading = false;

                                                                  WebSocketChannel? _channel;
                                                                    StreamSubscription<Uint8List>? _audioStreamSubscription;

                                                                      Future<void> _connectToServer() async {
                                                                          final ip = _ipController.text.trim();
                                                                              if (ip.isEmpty) {
                                                                                    _showMessage('الرجاء إدخال عنوان IP الخاص بالكمبيوتر');
                                                                                          return;
                                                                                              }

                                                                                                  setState(() => _isLoading = true);
                                                                                                      try {
                                                                                                            _channel?.sink.close();
                                                                                                                  _serverIp = ip;
                                                                                                                        _channel = IOWebSocketChannel.connect(Uri.parse('ws://$_serverIp:8080/ws'));
                                                                                                                              setState(() {
                                                                                                                                      _status = AppStatus.connected;
                                                                                                                                            });
                                                                                                                                                  _showMessage('تم الاتصال بـ $_serverIp');
                                                                                                                                                      } catch (e) {
                                                                                                                                                            _showMessage('فشل الاتصال: $e');
                                                                                                                                                                } finally {
                                                                                                                                                                      setState(() => _isLoading = false);
                                                                                                                                                                          }
                                                                                                                                                                            }

                                                                                                                                                                              Future<void> _startTalking() async {
                                                                                                                                                                                  if (_status != AppStatus.connected) return;

                                                                                                                                                                                      final hasPermission = await _audioRecorder.hasPermission();
                                                                                                                                                                                          if (!hasPermission) {
                                                                                                                                                                                                _showMessage('يجب السماح بإذن الميكروفون من إعدادات الجهاز');
                                                                                                                                                                                                      return;
                                                                                                                                                                                                          }

                                                                                                                                                                                                              setState(() {
                                                                                                                                                                                                                    _status = AppStatus.talking;
                                                                                                                                                                                                                          _currentTalkTime = 0;
                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                  try {
                                                                                                                                                                                                                                        final stream = await _audioRecorder.startStream(
                                                                                                                                                                                                                                                const RecordConfig(
                                                                                                                                                                                                                                                          encoder: AudioEncoder.pcm16bits,
                                                                                                                                                                                                                                                                    sampleRate: 44100,
                                                                                                                                                                                                                                                                              numChannels: 1,
                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                  _audioStreamSubscription = stream.listen((data) {
                                                                                                                                                                                                                                                                                                          _channel?.sink.add(data);
                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                    } catch (e) {
                                                                                                                                                                                                                                                                                                                          _showMessage('خطأ أثناء بدء التسجيل: $e');
                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                  _talkTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
                                                                                                                                                                                                                                                                                                                                        _currentTalkTime++;
                                                                                                                                                                                                                                                                                                                                              if (_currentTalkTime >= _maxDuration) {
                                                                                                                                                                                                                                                                                                                                                      _stopTalking();
                                                                                                                                                                                                                                                                                                                                                              _showMessage('انتهت المهلة القصوى ($_maxDuration ثانية)');
                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                            setState(() {});
                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                          Future<void> _stopTalking() async {
                                                                                                                                                                                                                                                                                                                                                                                              _talkTimer?.cancel();
                                                                                                                                                                                                                                                                                                                                                                                                  await _audioStreamSubscription?.cancel();
                                                                                                                                                                                                                                                                                                                                                                                                      _audioStreamSubscription = null;

                                                                                                                                                                                                                                                                                                                                                                                                          if (await _audioRecorder.isRecording()) {
                                                                                                                                                                                                                                                                                                                                                                                                                await _audioRecorder.stop();
                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                        if (_status == AppStatus.talking) {
                                                                                                                                                                                                                                                                                                                                                                                                                              setState(() {
                                                                                                                                                                                                                                                                                                                                                                                                                                      _status = AppStatus.connected;
                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    Color _getStatusColor() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        switch (_status) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              case AppStatus.disconnected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return Colors.orangeAccent;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case AppStatus.connected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return Colors.green;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          case AppStatus.talking:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return Colors.red;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        case AppStatus.receiving:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Colors.blue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String _getStatusText() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            switch (_status) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case AppStatus.disconnected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return "غير متصل - أدخل IP الكمبيوتر واضغطي اتصال";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                case AppStatus.connected:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return "متصل وجاهز (IP: $_serverIp)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              case AppStatus.talking:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return "جاري الإرسال... (${_maxDuration - _currentTalkTime} ثانية متبقية)";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            case AppStatus.receiving:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "جاري استقبال صوت...";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            void _showMessage(String text) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!mounted) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(text)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          void dispose() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              _talkTimer?.cancel();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  _audioStreamSubscription?.cancel();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      _channel?.sink.close();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          _audioRecorder.dispose();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              super.dispose();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  @override
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Widget build(BuildContext context) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return Scaffold(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              appBar: AppBar(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      title: const Text('تطبيق إضغط للتحدث PTT'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              centerTitle: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          body: Padding(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  padding: const EdgeInsets.all(20.0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Row(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Expanded(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: TextField(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    controller: _ipController,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        keyboardType: TextInputType.text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            decoration: const InputDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  labelText: 'IP الكمبيوتر',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hintText: 'مثال: 192.168.43.52',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              border: OutlineInputBorder(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const SizedBox(width: 10),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ElevatedButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onPressed: _isLoading ? null : _connectToServer,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: ElevatedButton.styleFrom(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            padding: const EdgeInsets.symmetric(vertical: 20, horizontal: 15),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: _isLoading
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ? const CircularProgressIndicator(color: Colors.white)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            : const Text('اتصال'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const SizedBox(height: 25),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Container(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            width: double.infinity,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          padding: const EdgeInsets.all(15),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        color: _getStatusColor(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        borderRadius: BorderRadius.circular(10),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: Text(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _getStatusText(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    textAlign: TextAlign.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style: const TextStyle(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color: Colors.white,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fontWeight: FontWeight.bold,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fontSize: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const Spacer(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            GestureDetector(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onTapDown: (_) => _startTalking(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        onTapUp: (_) => _stopTalking(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onTapCancel: () => _stopTalking(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    child: AnimatedContainer(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    duration: const Duration(milliseconds: 150),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    width: 200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    height: 200,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    decoration: BoxDecoration(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color: _status == AppStatus.talking ? Colors.red : Colors.blueGrey[900],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        shape: BoxShape.circle,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: Border.all(color: _getStatusColor(), width: 6),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            boxShadow: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                BoxShadow(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      color: _getStatusColor().withOpacity(0.4),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            blurRadius: 25,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  spreadRadius: 8,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        child: Column(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          mainAxisAlignment: MainAxisAlignment.center,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            children: [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Icon(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Icons.mic,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            size: 70,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  color: _status == AppStatus.talking ? Colors.white : Colors.white70,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
